INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1011, '数学', '三年级', '应用题', 3, '{"stem": "学校买来8包练习本，每包12袋，每袋6本。三年级有5个班，每班36人。学校一共买了多少本练习本？三年级学生每人发3本够不够？", "options": null}', '共买576本；需要540本；够（余36本）', '总本数：8×12×6=576（本）；3 年级学生：5×36=180（人），每人3本共 180×3=540（本）。576>540，够（还剩 36 本）。', 'paper', '["practice", "ykl3sx", "2.5"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
