INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1018, '数学', '三年级', '填空', 3, '{"stem": "填空：算式 A4×A（A>0），如果积是两位数，那么较大的A是（ ）；如果积的末尾有0，A可以填（ ）。", "options": null}', 'A=2；A=5', '积两位数：A=2 时 24×2=48 ✓，A=3 时 34×3=102（三位），故较大 A=2。积末尾有 0：4×A 末位为 0 → A=5（5×4=20），54×5=270 ✓。', 'paper', '["practice", "ykl3sx", "2.5"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1018, '数学', '三年级', '填空', 3, '{"stem": "一个两位数乘3，如果得到的积是两位数，这个两位数最大是（ ）；如果得到的积是三位数，这个两位数最小是（ ）。", "options": null}', '33；34', '两位数×3 积两位：33×3=99 ✓，34×3=102（三位）→ 最大 33；最小 34。', 'paper', '["practice", "ykl3sx", "2.5"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1018, '数学', '三年级', '拓展', 3, '{"stem": "将下面的算式按要求连线（连一连），组成符合条件的一位数乘两位数算式：\n条件①积是两位数；条件②积在400和500之间；条件③积的末尾有0；条件④积是三位数且小于250。\n候选算式：23×4、23×3、7×61、61×8、5×48、4×75、75×8、7×23、23×5、23×8、61×4、61×3、48×4、75×3、48×3。", "options": null}', '①积两位数：23×4=92，23×3=69；②积在400~500：7×61=427，61×8=488；③积末尾有0：5×48=240，4×75=300，75×8=600；④积三位且<250：7×23=161，23×5=115，23×8=184，5×48=240，61×4=244，61×3=183，48×4=192，75×3=225，48×3=144', '逐条筛选：①需积≤99 → 23×4=92、23×3=69；②需400≤积<500 → 7×61=427、61×8=488；③需积末位为0 → 5×48=240、4×75=300、75×8=600；④需100≤积<250 → 上述余项均符合。', 'paper', '["practice", "ykl3sx", "2.5"]', NULL, 0);
